CREATE COLUMN TABLE "TEST_AP"."FNS1" ("Series" INTEGER CS_INT NOT NULL , "FolNumFrom" INTEGER CS_INT NOT NULL , "FolNumTo" INTEGER CS_INT NOT NULL , "Reason" NVARCHAR(100), PRIMARY KEY ("Series", "FolNumFrom")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "FNS1_To" ON "TEST_AP"."FNS1" ( "Series" ASC, "FolNumTo" ASC )